const manuscript = $('Fetch Manuscript').first().json;
const chapters = $('Fetch Chapters').all().map(item => item.json);

console.log('Processing manuscript:', manuscript.title);
console.log('Total chapters:', chapters.length);

// Calculate actual total word count from all chapters
const fullText = chapters.map(c => c.content).filter(c => c).join('\n\n');
const actualWordCount = fullText.split(/\s+/).filter(w => w.length > 0).length;

// Build structure for analysis nodes
const manuscriptData = {
  manuscriptId: manuscript.id,
  authorName: manuscript.author_name || 'Author',
  manuscriptTitle: manuscript.title,
  genre: manuscript.genre || 'Fiction',
  totalWordCount: actualWordCount, // ← Changed from wordCount
  totalChapters: chapters.length,   // ← Changed from chapterCount

  // Full text for analysis
  fullText: fullText,

  // Structured chapters with all data (keep for other uses)
  chapters: chapters.map((ch, index) => ({
    chapterId: ch.id,
    chapterNumber: ch.chapter_number,
    title: ch.title || `Chapter ${ch.chapter_number}`,
    content: ch.content,
    wordCount: ch.content ? ch.content.split(/\s+/).filter(w => w.length > 0).length : 0,
    previousChapterTitle: index > 0 ? chapters[index - 1].title : null,
    nextChapterTitle: index < chapters.length - 1 ? chapters[index + 1].title : null,
    progressPercent: Math.round(((index + 1) / chapters.length) * 100)
  })),

  // Story context for AI nodes (keep for compatibility)
  storyContext: {
    totalChapters: chapters.length,
    genre: manuscript.genre || 'Unknown',
    totalWordCount: actualWordCount
  },

  // Metadata
  analysisDate: new Date().toLocaleDateString('en-US', { 
    year: 'numeric', 
    month: 'long', 
    day: 'numeric' 
  })
};

console.log('Processed data:', JSON.stringify({
  title: manuscriptData.manuscriptTitle,
  totalChapters: manuscriptData.totalChapters,
  totalWordCount: manuscriptData.totalWordCount,
  genre: manuscriptData.genre
}, null, 2));

return { json: manuscriptData };

// Final Response - Code Node (JavaScript)
// This creates the final success response for the main workflow

return {
  json: {
    success: true,
    message: "Phase 1 analysis completed successfully",
    submissionId: $json.submissionId,
    authorName: $json.authorName,
    bookTitle: $json.bookTitle,
    wordCount: $json.wordCount,
    analysisComplete: true,
    emailDelivered: true,
    processingTime: new Date().toISOString(),
    status: "completed",

    // Additional useful data
    phaseType: "developmental_analysis",
    phaseNumber: 1,
    reportGenerated: true,
    s3Key: $json.s3Key || null,
    accessToken: $json.accessToken || null
  }
};

const cellReturn = $input.first().json;
return [{ json: {
  output: cellReturn.ok ? (cellReturn.content || '') : '',
  ok: !!cellReturn.ok,
  cell_terminal_reason: cellReturn.ok ? null : (cellReturn.terminal_reason || 'unknown'),
  cell_model: cellReturn.model || null,
  cell_input_tokens: cellReturn.input_tokens || null,
  cell_output_tokens: cellReturn.output_tokens || null,
  cell_latency_ms: cellReturn.latency_ms || null,
  cell_cost_usd: cellReturn.cost_estimate_usd || null
}}];

