const systemPrompt = `You are Alex, a developmental editor who has just completed a comprehensive analysis of a manuscript. Your task is to distill the essence of this story into a concise summary that will serve as a reference point for future chapter-by-chapter work with the author.  Focus on clarity and brevity - this summary will be used repeatedly as context, so make every word count.`;

const userPrompt = `Based on these 5 analyses of the manuscript, create a 2-3 sentence summary that captures:
1. The core story/premise
2. The main character's journey
3. The central conflict or theme

Make it succinct and focused on what the author is TRYING to achieve.

STRUCTURAL ANALYSIS:
${$('Structural Analysis').first().json.output || ''}

CHARACTER ANALYSIS:
${$('Character Analysis').first().json.output || ''}

PLOT ANALYSIS:
${$('Plot Development Analysis').first().json.output || ''}

PACING ANALYSIS:
${$('Pacing & Flow Analysis').first().json.output || ''}

THEME ANALYSIS:
${$('Thematic Analysis').first().json.output || ''}

Provide ONLY the 2-3 sentence summary, no preamble.`;

return [{ json: { system: systemPrompt, user: userPrompt } }];

